### Describe the bug

Unable to register mouse clicks in a blessed.js application, mouse movement appears to register correctly.



### To reproduce

0. enable mouse and scroll reporting in Warp settings.
1. `brew install node ; npm install blessed`
2. `vim test.js`
4. copy the mouse sample app to the test.js file
```sh
const blessed = require('blessed');

// Create a screen with mouse support
const screen = blessed.screen({
  smartCSR: true,
  mouse: true, // Enable mouse support
});

// Create a box
const box = blessed.box({
  top: 'center',
  left: 'center',
  width: '50%',
  height: '50%',
  content: 'Move your mouse and click inside the box!',
  tags: true,
  border: {
    type: 'line'
  },
  style: {
    fg: 'white',
    border: {
      fg: '#f0f0f0'
    }
  }
});

// Append the box to the screen
screen.append(box);

// Track mouse movements
screen.on('mousemove', function(data) {
  box.setContent(`Mouse position: ${data.x}, ${data.y}`);
  screen.render();
});

// Track mouse clicks
screen.on('mousedown', function(data) {
  box.setContent('Mouse clicked!');
  screen.render();
});

// Quit on Escape, q, or Control-C
screen.key(['escape', 'q', 'C-c'], function(ch, key) {
  return process.exit(0);
});

// Render the screen
screen.render();
```
3. run `node test.js`, play with the app, and notice how the movement is tracked, but not clicks. This works in other terminals like iTerm/terminal.app

